/// MMT Market Mechanism
#[repr(u8)]
#[derive(Debug, Copy, Clone, Eq, PartialEq, Serialize, Deserialize)]
pub enum MmtMarketMechanism {
  /// 1 = Central Limit Order Book
  CentralLimitOrderBook = 0x0001,
  /// 2 = Quote Driven Market
  QuoteDrivenMarket = 0x0002,
  /// 3 = Dark Order Book
  DarkOrderBook = 0x0003,
  /// 4 = Off Book
  OffBook = 0x0004,
  /// 5 = Periodic Auction
  PeriodicAuction = 0x0005,
  /// 6 = Request For Quotes
  RequestForQuotes = 0x0006,
  /// 7 = Any other including Hybrid
  Other = 0x0007,
}
impl Default for MmtMarketMechanism {
  fn default() -> Self {
    Self::CentralLimitOrderBook
  }
}
impl std::convert::TryFrom<u8> for MmtMarketMechanism {
  type Error = InvalidVariant;
  fn try_from(value: u8) -> Result<Self, Self::Error> {
    match value {
      0x0001 => Ok(Self::CentralLimitOrderBook),
      0x0002 => Ok(Self::QuoteDrivenMarket),
      0x0003 => Ok(Self::DarkOrderBook),
      0x0004 => Ok(Self::OffBook),
      0x0005 => Ok(Self::PeriodicAuction),
      0x0006 => Ok(Self::RequestForQuotes),
      0x0007 => Ok(Self::Other),
      other => Err(InvalidVariant::new(other as u32, "MmtMarketMechanism")),
    }
  }
}

